r"""Witt index one by the Hilbert modular model (#40).

Let `E` be a real quadratic field with maximal order `O`. The lattice `L` of
Hermitian matrices `X = [[a, \beta], [\bar\beta, d]]`, `a, d \in Z`, `\beta \in O`, with
`q(X) = -2 det X = -2ad + 2 N(\beta)` is `U + (O, Tr(x \bar y))`. A matrix `g \in SL_2(O)` acts by
`X \mapsto g X \bar g^t`.

**Generation of `SL_2(O)`.** `O^*` is infinite, so `SL_2(O)` is generated by the elementary matrices
`E_{12}(b)`, `E_{21}(b)` (L. N. Vaserstein, *On the group SL_2 over Dedekind rings of arithmetic type*,
Mat. Sb. 89 (1972); Math. USSR-Sb. 18 (1972) 321-332). The maps `b -> E_{12}(b)` and
`b -> E_{21}(b)` are homomorphisms from `(O, +)`, so `b` may run over a `Z`-basis of `O`. The swap
`w = [[0, 1], [-1, 0]] = E_{12}(1) E_{21}(-1) E_{12}(1)` gives `E_{21}(b) = w^{-1} E_{12}(-b) w`, so
`<w, E_{12}(1), E_{12}(\omega)> = SL_2(O)`. No Euclidean algorithm is used.

**Cusps.** A primitive null `X` is `\pm u \bar u^t` for a nonzero column `u` of `X`, rescaled. The
`SL_2(O)`-orbits of primitive null vectors are the cusps, one per ideal class of `O`
(:mod:`witt_one_fixed_norm_classes`). Let `e = E_{11}` (principal cusp), `H = <SL_2(O), -1>`, and let `l_c`
be an element of `O(L)` with `l_c e_c = e` for each cusp vector `e_c` in the `O(L)`-orbit of `e`. For
`g \in O(L)`, `g e = \pm h e_c` for some `h \in H` and cusp `c`, and then `l_c h^{-1} (\pm g)` fixes `e`. So
`O(L) = <H, Stab(e), l_c>`. `Stab(e)` is the Eichler shears, which are the upper triangular elements of
`SL_2(O)`, extended by `O(K)` for `K = (O, Tr)`; `O(K)` is generated by `-1`, multiplication by a generator
of the norm-one units, and conjugation. The links `l_c` are decided exactly by
:meth:`HilbertFixedNormClasses.cusp_links`.
"""

from itertools import product

from sage.matrix.constructor import matrix
from sage.matrix.special import identity_matrix
from sage.modules.free_module_element import vector
from sage.rings.integer_ring import ZZ
from sage.rings.number_field.number_field import QuadraticField
from sage.rings.rational_field import QQ


class HilbertWittOneLattice:
    r"""The lattice `U + (O_E, Tr)` for ``E = Q(sqrt(D))``, with coordinates `(a, d, x, y)`."""

    def __init__(self, D):
        self.D = D
        self.field = QuadraticField(D, "s")
        self.conjugate = self.field.automorphisms()[1]
        self.order = self.field.ring_of_integers()
        root = self.field.gen()
        self.omega = (1 + root) / 2 if D % 4 == 1 else root
        self._beta_basis = (self.field.one(), self.omega)
        self._coordinates = matrix(QQ, [list(b.vector()) for b in self._beta_basis]).inverse()

    def _beta(self, x, y):
        return x * self._beta_basis[0] + y * self._beta_basis[1]

    def _beta_coordinates(self, beta):
        return vector(QQ, list(beta.vector())) * self._coordinates

    def _matrix_of(self, v):
        a, d, x, y = v
        beta = self._beta(x, y)
        return matrix(self.field, 2, 2, [a, beta, self.conjugate(beta), d])

    def _vector_of(self, m):
        x, y = self._beta_coordinates(m[0, 1])
        return vector(QQ, [QQ(m[0, 0]), QQ(m[1, 1]), x, y])

    def gram(self):
        basis = identity_matrix(ZZ, 4).rows()

        def b(u, v):
            first, second = self._beta(u[2], u[3]), self._beta(v[2], v[3])
            return -(u[0] * v[1] + u[1] * v[0]) + (first * self.conjugate(second)).trace()

        return matrix(ZZ, [[b(u, v) for v in basis] for u in basis])

    def action(self, g):
        r"""Return the matrix of `X \mapsto g X \bar g^t` on the coordinates."""
        conjugate_transpose = g.apply_map(self.conjugate).transpose()
        columns = [self._vector_of(g * self._matrix_of(v) * conjugate_transpose) for v in identity_matrix(ZZ, 4).rows()]
        return matrix(ZZ, columns).transpose()

    def linear_action(self, function):
        columns = [function(v) for v in identity_matrix(ZZ, 4).rows()]
        return matrix(ZZ, columns).transpose()

    def _unit_rotation(self, unit):
        def function(v):
            x, y = self._beta_coordinates(unit * self._beta(v[2], v[3]))
            return vector(ZZ, [v[0], v[1], x, y])

        return self.linear_action(function)

    def norm_one_unit(self):
        r"""Return a generator modulo `\pm 1` of the norm-one units of `O`."""
        unit = self.field(self.field.unit_group().fundamental_units()[0])
        return unit if unit.norm() == 1 else unit**2

    def generators(self):
        r"""Return generators of `<SL_2(O), -1, Stab(e)>`, as matrices on the coordinates.

        With class number one this is `O(L)`; otherwise :func:`recognized_generators` adds the cusp links.
        """
        E = self.field
        one, zero = E.one(), E.zero()
        negate = -identity_matrix(ZZ, 4)
        swap = matrix(E, 2, 2, [zero, one, -one, zero])
        shears = [matrix(E, 2, 2, [one, b, zero, one]) for b in self._beta_basis]

        def conjugation(v):
            x, y = self._beta_coordinates(self.conjugate(self._beta(v[2], v[3])))
            return vector(ZZ, [v[0], v[1], x, y])

        return (
            self.action(swap),
            *(self.action(s) for s in shears),
            negate,
            self._unit_rotation(-E.one()),
            self._unit_rotation(self.norm_one_unit()),
            self.linear_action(conjugation),
        )

    def _coprime_factor(self, v):
        r"""Return `(sign, u)` with `X = sign \cdot u \bar u^t` for a primitive null vector."""
        m = self._matrix_of(v)
        if m[0, 0] == 0 and m[1, 1] == 0:
            raise ArithmeticError("a null Hermitian matrix with zero diagonal has zero off-diagonal")
        if m[0, 0] != 0:
            first, second = m[0, 0], self.conjugate(m[0, 1])
        else:
            first, second = m[1, 0], m[1, 1]
        generator = self.field.ideal(first, second).gens_reduced()[0]
        u = vector(self.field, [first / generator, second / generator])
        product = matrix(
            self.field, 2, 2,
            [u[0] * self.conjugate(u[0]), u[0] * self.conjugate(u[1]), u[1] * self.conjugate(u[0]), u[1] * self.conjugate(u[1])],
        )
        position = 0 if m[0, 0] != 0 else 1
        factor = m[position, position] / product[position, position]
        if factor not in (1, -1) or factor * product != m:
            raise ArithmeticError(f"{v} is not plus or minus a product of a coprime vector")
        return ZZ(factor), u

    def _reduce_pair(self, u):
        r"""Return `g \in SL_2(O)` with `g u = (1, 0)` up to a unit, by Euclidean division.

        Only a norm-Euclidean `O` admits the division; otherwise the step raises ``ArithmeticError``.
        """
        E = self.field
        one, zero = E.one(), E.zero()
        g = identity_matrix(E, 2)
        swap = matrix(E, 2, 2, [zero, one, -one, zero])
        current = vector(E, u)
        while current[1] != 0:
            quotient = self._nearest_integer(current[0] / current[1])
            shear = matrix(E, 2, 2, [one, -quotient, zero, one])
            current = swap * (shear * current)
            g = swap * shear * g
        return g, current

    def _nearest_integer(self, value):
        r"""Return the element of `O` with `|N(value - q)|` minimal among nearby candidates."""
        x, y = self._beta_coordinates(value)
        candidates = [self._beta(x.round() + i, y.round() + j) for i in range(-2, 3) for j in range(-2, 3)]
        best = min(candidates, key=lambda c: abs((value - c).norm()))
        if abs((value - best).norm()) >= 1:
            raise ArithmeticError(f"the order of Q(sqrt({self.D})) did not give a Euclidean step at {value}")
        return best

    def transporter_to_e(self, v):
        r"""Return `h \in O(L)` with `h v = e` up to a unit action, for a primitive null `v`."""
        v = vector(ZZ, v)
        sign, u = self._coprime_factor(v)
        g, end = self._reduce_pair(u)
        h = self.action(g)
        if sign == -1:
            h = -h
        image = h * v
        unit = end[0]
        norm = unit.norm()
        if norm == -1:
            image = -image
            h = -h
        if tuple(image) != (1, 0, 0, 0):
            raise ArithmeticError(f"the reduction of {v} ended at {tuple(image)}")
        return h


def recognized_model(lattice):
    r"""Return ``(model, basis)`` when ``L`` is isometric to a Hilbert model, or ``None``.

    Columns of ``basis`` are the images of the model coordinates. Finds a hyperbolic plane in a small box, splits it off, and matches the complement with the
    trace form of `O_E` for `E = Q(\sqrt{D})`, `D` the squarefree part of `|\det L|`. Generators of
    the model are conjugated back. Finding no plane or no match in the box returns ``None``,
    which is no statement about `L`.
    """
    frame = tuple(lattice.module_generators())
    if len(frame) != 4:
        return None
    gram = matrix(ZZ, [[int(lattice.b(x, y)) for y in frame] for x in frame])
    determinant = abs(gram.det())
    D = determinant.squarefree_part()
    if D == 1 or QuadraticField(D, "s").discriminant() != determinant:
        return None
    model = HilbertWittOneLattice(D)
    target = model.gram()[2:, 2:]
    box = [vector(ZZ, v) for v in product(range(-3, 4), repeat=4) if any(v)]
    null = [v for v in box if (v * gram * v) == 0]
    for e in null:
        for f in null:
            if e * gram * f != -1:
                continue
            complement = matrix(ZZ, [e * gram, f * gram]).right_kernel().basis_matrix()
            if complement.nrows() != 2:
                continue
            block = complement * gram * complement.transpose()
            for entries in product(range(-6, 7), repeat=4):
                change = matrix(ZZ, 2, 2, entries)
                if abs(change.det()) == 1 and change * block * change.transpose() == target:
                    basis = matrix(ZZ, [e, f]).stack(change * complement).transpose()
                    if abs(basis.det()) != 1:
                        continue
                    return model, basis
    return None


def recognized_generators(lattice):
    r"""Return ``O(L)`` generators when ``L`` is isometric to a Hilbert model, or ``None``.

    The model generators generate `<SL_2(O), -1, Stab(e)>` by Vaserstein's theorem; the cusp links join
    the cusps in the ``O(L)``-orbit of `e` (module docstring).
    """
    from sage_indefinite_port.indefinite.witt_one_fixed_norm_classes import HilbertFixedNormClasses

    recognized = recognized_model(lattice)
    if recognized is None:
        return None
    model, basis = recognized
    inverse = basis.inverse()
    generators = (*model.generators(), *HilbertFixedNormClasses(model).cusp_links())
    return tuple(basis * g * inverse for g in generators)
